message:
Running command: bash /workspace/build.sh 'cd /gt/_work/src/test && cat > /tmp/fuzz_debug.c << "EOF"
#define MG_ENABLE_SOCKET 0
#define MG_ENABLE_LOG 0
#define MG_ENABLE_LINES 1
#define MG_ENABLE_TCPIP 1
#define MG_IO_SIZE (32 * 1024 * 1024)
#include "mongoose.c"
#include "driver_mock.c"
#include <stdio.h>

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  struct mg_mqtt_message mm;
  int rc = mg_mqtt_parse(data, size, 5, &mm);
  fprintf(stderr, "MQTT parse rc=%d size=%zu\n", rc, size);
  if (rc == MQTT_OK) {
    fprintf(stderr, "dgram.len=%zu props_start=%zu props_size=%zu\n", mm.dgram.len, mm.props_start, mm.props_size);
    struct mg_mqtt_prop prop;
    size_t ofs = 0;
    while ((ofs = mg_mqtt_next_prop(&mm, &prop, ofs)) > 0) {
      fprintf(stderr, "prop ofs=%zu\n", ofs);
    }
  }
  return 0;
}

int main(int argc, char *argv[]) {
  if (argc > 1) {
    FILE *f = fopen(argv[1], "rb");
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *buf = malloc(sz);
    fread(buf, 1, sz, f);
    fclose(f);
    LLVMFuzzerTestOneInput(buf, sz);
    free(buf);
  }
  return 0;
}
EOF
gcc -g -fsanitize=address -I. /tmp/fuzz_debug.c -o /tmp/fuzz_debug 2>&1 | tail -5 && python3 -c "
poc = bytes([0x30, 0x07, 0x00, 0x01, 0x61, 0x80, 0x80, 0x80, 0x00])
with open('/tmp/poc.bin', 'wb') as f:
    f.write(poc)
" && /tmp/fuzz_debug /tmp/poc.bin 2>&1 | head -30'

